PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS settings (id INTEGER PRIMARY KEY AUTOINCREMENT, key TEXT UNIQUE NOT NULL, value TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS contacts (id INTEGER PRIMARY KEY AUTOINCREMENT, first_name TEXT NOT NULL, last_name TEXT DEFAULT '', nickname TEXT DEFAULT '', dob TEXT, email TEXT DEFAULT '', phone TEXT DEFAULT '', phone2 TEXT DEFAULT '', address TEXT DEFAULT '', city TEXT DEFAULT '', state TEXT DEFAULT '', zip TEXT DEFAULT '', country TEXT DEFAULT 'USA', relationship TEXT DEFAULT 'Friend', gender TEXT DEFAULT '', pronouns TEXT DEFAULT '', company TEXT DEFAULT '', job_title TEXT DEFAULT '', tags TEXT DEFAULT '', notes TEXT DEFAULT '', is_favorite INTEGER DEFAULT 0, avatar_color TEXT DEFAULT '#6366f1', how_we_met TEXT DEFAULT '', anniversary TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS accounts (id INTEGER PRIMARY KEY AUTOINCREMENT, contact_id INTEGER NOT NULL REFERENCES contacts(id) ON DELETE CASCADE, label TEXT NOT NULL, type TEXT DEFAULT 'Other', username TEXT DEFAULT '', email TEXT DEFAULT '', password TEXT DEFAULT '', website TEXT DEFAULT '', bank_name TEXT DEFAULT '', routing_number TEXT DEFAULT '', account_number TEXT DEFAULT '', account_type TEXT DEFAULT '', notes TEXT DEFAULT '', is_primary INTEGER DEFAULT 0, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS journal_entries (id INTEGER PRIMARY KEY AUTOINCREMENT, contact_id INTEGER NOT NULL REFERENCES contacts(id) ON DELETE CASCADE, entry_date TEXT NOT NULL, title TEXT NOT NULL, entry_type TEXT DEFAULT 'Note', is_intimate INTEGER DEFAULT 0, mood TEXT DEFAULT '', location TEXT DEFAULT '', notes TEXT DEFAULT '', rating INTEGER DEFAULT 0, intimacy_type TEXT DEFAULT '', protection_used TEXT DEFAULT '', contraception_notes TEXT DEFAULT '', consent_confirmed INTEGER DEFAULT 0, duration_minutes INTEGER DEFAULT 0, satisfaction INTEGER DEFAULT 0, partner_satisfaction INTEGER DEFAULT 0, emotional_closeness INTEGER DEFAULT 0, communication_rating INTEGER DEFAULT 0, activities TEXT DEFAULT '', position_notes TEXT DEFAULT '', orgasm TEXT DEFAULT '', aftercare TEXT DEFAULT '', mood_before TEXT DEFAULT '', mood_after TEXT DEFAULT '', health_concerns TEXT DEFAULT '', sti_tested_recent INTEGER DEFAULT 0, would_repeat TEXT DEFAULT '', what_went_well TEXT DEFAULT '', what_to_improve TEXT DEFAULT '', is_private INTEGER DEFAULT 1, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
